/**
 * audiochat Gemini Live API (WebSocket) chat driver.
 *
 * Implements the same driver interface as chatdriver_openai but uses the
 * Gemini Live API over a WebSocket, streaming 16 kHz PCM audio up and playing
 * 24 kHz PCM audio down via the Web Audio API.
 *
 * Backend contract: the driver fetches geminilive.php?contextid=N and expects
 * JSON {url, ephemeralToken, model} used to open the WebSocket.
 *
 * @module     minilessonitem_audiochat/chatdriver_gemini
 * @copyright  2026 Justin Hunt (poodllsupport@gmail.com)
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(['jquery', 'core/log', 'core/fragment', 'core/ajax'],
        function ($, log, Fragment, Ajax) {
    "use strict";

    log.debug('MiniLesson AudioChat: Gemini driver loading');

    var INPUT_SAMPLE_RATE = 16000;
    var OUTPUT_SAMPLE_RATE = 24000;
    var DEFAULT_MODEL = 'gemini-3.1-flash-live-preview';

    // How the boundaries of a user turn are decided. The server reports which mode it
    // baked into the ephemeral token, because the Constrained endpoint honours the
    // token's setup rather than the setup we send over the wire.
    //   auto   – Auto Send on. Server VAD decides both ends of the turn.
    //   hybrid – Auto Send off, server VAD enabled but with a silence window too long
    //            to ever fire, so our audioStreamEnd finalises the turn instead. The
    //            VAD still decides whether speech happened, so silence is never a turn.
    //   manual – Auto Send off, VAD disabled, we delimit turns with activityStart /
    //            activityEnd. The fallback for a provider that does not report a mode.
    var TURNMODE_AUTO = 'auto';
    var TURNMODE_HYBRID = 'hybrid';
    var TURNMODE_MANUAL = 'manual';
    // Must match MINILESSON_AUDIOCHAT_HYBRID_SILENCE_MS in geminilive.php.
    var HYBRID_SILENCE_MS = 60000;
    // How long a student may pause in auto mode before the model takes its turn. The
    // real value is the admin setting, delivered in itemdata; this is only the fallback
    // for itemdata that predates it. Keep in step with DEFAULT_SILENCEDURATION in
    // classes/itemtype.php.
    var DEFAULT_SILENCE_MS = 3500;

    // Manual (Auto Send off) speech gating. With automaticActivityDetection disabled
    // we delimit the user turn ourselves, and Gemini treats whatever falls between
    // activityStart and activityEnd as a turn it must transcribe. A turn holding only
    // silence makes it hallucinate a transcript (typically stock Spanish phrases), so
    // we do not open the activity at all until we actually hear something.
    // RMS of a normalised (-1..1) frame; room tone sits well below this.
    var SPEECH_RMS_THRESHOLD = 0.015;
    // Frames above the threshold before we call it speech, to ignore clicks and pops.
    var SPEECH_FRAMES_REQUIRED = 2;
    // Frames of pre-roll kept back so the first syllable is not clipped.
    // 4096 samples/frame at 16 kHz is ~256 ms/frame.
    var SPEECH_PREROLL_FRAMES = 2;

    return {
        // Runtime state.
        itemdata: {},
        audioElement: null,
        autoCreateResponseToggleWrapperElement: null,
        callbacks: {},

        // Transport.
        ws: null,
        mediaStream: null,
        inputAudioCtx: null,
        outputAudioCtx: null,
        scriptProcessor: null,
        sourceNode: null,
        _micEnabled: false,
        _setupComplete: false,
        // Turn mode in force for this connection, from the token endpoint. Manual
        // until the server tells us otherwise, so a provider that reports nothing
        // keeps the old hand-delimited behaviour.
        turnmode: TURNMODE_MANUAL,
        // Manual-turn speech gating (manual mode only). _activityOpen tracks whether
        // we have sent activityStart for the current mic-on period, so activityEnd is
        // only ever sent to close an activity we really opened.
        _activityOpen: false,
        _awaitingSpeech: false,
        _speechFrameCount: 0,
        _prerollFrames: [],
        // True when WE are closing the socket on purpose (stop/grading/reconnect),
        // so the onclose handler does not treat it as an expiry to recover from.
        _intentionalClose: false,

        // Conversation state.
        items: {},
        loadingMessages: null,
        currentUserItemId: null,
        currentAssistantItemId: null,
        itemCounter: 0,

        // Playback scheduling for raw PCM output.
        nextPlayTime: 0,

        // BCP-47 language hint for the input transcription, from the token endpoint.
        inputlanguage: '',

        // Grading.
        gradingData: false,

        // Diagnostics: when this connection opened, and the latest usageMetadata from the server.
        _openedAt: null,
        _lastUsage: null,

        // Session options.
        audiochat_voice: 'Aoede',
        autocreateresponse: false,
        silencedurationms: DEFAULT_SILENCE_MS,
        datainputbuffer: false,
        setupConfig: {
            model: 'models/' + DEFAULT_MODEL,
            generationConfig: {
                responseModalities: ['AUDIO'],
                temperature: 0.7,
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: {
                            voiceName: self.audiochat_voice
                        }
                    }
                }
            },
            realtimeInputConfig: {
                automaticActivityDetection: {
                    disabled: false,
                    silenceDurationMs: DEFAULT_SILENCE_MS,
                }
            },
            sessionResumption: {},
            // Lets the session outlive the raw context window so resumption is not
            // defeated by the context limit a little after the connection limit.
            contextWindowCompression: {
                slidingWindow: {}
            },
            inputAudioTranscription: {},
            outputAudioTranscription: {}
        },
        sessionResumptionToken: null,
        resumingSession: false,
        // After a reconnect, the interrupted turn never sends turnComplete on the new
        // socket, so the mic would stay muted. This flag tells the setupComplete
        // handler to hand the turn back to the user once the resume is established.
        _restoreMicOnResume: false,

        clone: function () {
            return $.extend(true, {}, this);
        },

        init: function (options) {
            var self = this;
            self.itemdata = options.itemdata;
            self.cmid = options.cmid;
            self.audioElement = options.audioElement;
            self.autoCreateResponseToggleWrapperElement = options.autoCreateResponseToggleWrapperElement;
            self.callbacks = options.callbacks || {};
            self.autocreateresponse = options.itemdata.audiochat_autoresponse || false;
            self.silencedurationms = options.itemdata.audiochat_silenceduration || DEFAULT_SILENCE_MS;
            self.audiochat_voice = self._resolveVoice(options.itemdata.audiochat_voice);
            self.items = {};
            self.loadingMessages = new Set();
            self.gradingData = false;
            self.itemCounter = 0;
            self.currentUserItemId = null;
            self.currentAssistantItemId = null;
            self._pendingFirstMessage = null;
            self._setupComplete = false;
            self._activityOpen = false;
            self._awaitingSpeech = false;
            self._speechFrameCount = 0;
            self._prerollFrames = [];
            self.autoCreateResponseToggleWrapperElement.style.display = 'none';
        },

        _resolveVoice: function (voice) {
            var voiceMap = {
                'alloy': 'Aoede', 'ash': 'Charon', 'ballad': 'Kore',
                'coral': 'Aoede', 'echo': 'Puck', 'sage': 'Charon',
                'shimmer': 'Aoede', 'verse': 'Puck', 'marin': 'Fenrir', 'cedar': 'Charon',
            };
            var geminiVoices = ['Aoede', 'Charon', 'Fenrir', 'Kore', 'Puck'];
            if (voice && geminiVoices.includes(voice)) {
                return voice;
            }
            return voiceMap[voice] || 'Aoede';
        },

        // ── Callback helpers ──

        _fire: function (name) {
            var cb = this.callbacks[name];
            if (typeof cb === 'function') {
                cb.apply(null, Array.prototype.slice.call(arguments, 1));
            }
        },

        _notifyItems: function () {
            this._fire('onItemsChanged', this.getOrderedItems(), this.loadingMessages);
        },

        // ── Public getters (UI contract) ──

        getItems: function () { return this.items; },

        getOrderedItems: function () {
            return Object.values(this.items).sort(function (a, b) { return a.order - b.order; });
        },

        getGradingData: function () { return this.gradingData; },
        getMediaStream: function () { return this.mediaStream; },
        getLoadingMessages: function () { return this.loadingMessages; },

        setAutoCreateResponse: function (enabled) {
            var self = this;
            self.autocreateresponse = enabled;
            log.debug('Gemini driver: autocreate response toggled:');
            log.debug(enabled);
            // Toggling VAD requires a new setup, so resume the session on a fresh socket.
            self._reconnectSession();
        },

        /**
         * Open a fresh WebSocket and resume the current session using the stored
         * resumption handle. Used both when the connection limit is hit
         * (goAway / unexpected close) and when a setting change (VAD toggle)
         * requires a new setup. A fresh ephemeral token is fetched because the
         * token minted by geminilive.php is single-use.
         * @return {Promise|undefined}
         */
        _reconnectSession: function () {
            var self = this;
            if (self.resumingSession) {
                log.debug('Gemini: reconnect already in progress, skipping');
                return;
            }
            log.debug('Gemini: reconnecting session (resumption handle: ' +
                (self.sessionResumptionToken ? 'present' : 'none') + ')');
            self.resumingSession = true;
            self._setupComplete = false;
            self._restoreMicOnResume = true;
            self.currentUserItemId = null;
            self.currentAssistantItemId = null;
            self._fire('onStateChange', 'connecting');
            // Close the old socket BEFORE minting the new token, so no further
            // sessionResumptionUpdate can change the handle between the token mint
            // (_fetchSessionInfo) and the wire setup (_sendSetupAndFirstTurn).
            // Both must carry the same handle for the Constrained endpoint to resume.
            if (self.ws && self.ws.readyState === WebSocket.OPEN) {
                self._intentionalClose = true;
                try { self.ws.close(); } catch (e) { log.debug(e); }
            }
            return self._fetchSessionInfo().then(function (sessionInfo) {
                self._intentionalClose = false;
                // The new token carries its own turn mode, which differs from the old
                // one whenever the reconnect was caused by an Auto Send toggle.
                self.turnmode = self._resolveTurnMode(sessionInfo);
                self.inputlanguage = sessionInfo.inputlanguage || '';
                log.debug('Gemini: turn mode ' + self.turnmode);
                return self._openWebSocket(sessionInfo).then(function () {
                    // _sendSetupAndFirstTurn attaches sessionResumptionToken as the
                    // resumption handle and, because resumingSession is true, skips
                    // re-sending the intro turn. The mic pipeline is still alive, so
                    // audio frames resume flowing as soon as the socket is open.
                    self._sendSetupAndFirstTurn(sessionInfo.model);
                    self._fire('onStateChange', 'connected');
                });
            }).catch(function (err) {
                log.debug('Gemini: reconnect failed');
                log.debug(err);
                self.resumingSession = false;
                self._fire('onStateChange', 'error');
                self._fire('onError', err);
            });
        },

        setDataInputBuffer: function (value, source) {
            this.datainputbuffer = value;
            log.debug('Gemini driver: setDataInputBuffer');
            log.debug(value);
            log.debug(source);
        },

        // ── Session lifecycle ──

        start: async function () {
            var self = this;
            log.debug('Gemini driver: session starting');
            self._fire('onStateChange', 'connecting');
            self.items = {};
            self.loadingMessages = new Set();
            self._setupComplete = false;
            self._intentionalClose = false;
            self.resumingSession = false;
            self.sessionResumptionToken = null;
            self._notifyItems();

            // 1. Acquire mic.
            try {
                self.mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            } catch (err) {
                log.debug('Gemini driver: getUserMedia failed');
                log.debug(err);
                self._fire('onStateChange', 'error');
                self._fire('onError', err);
                return;
            }
            self._fire('onMediaStreamReady', self.mediaStream);

            // 2. Fetch ephemeral token.
            var sessionInfo;
            try {
                sessionInfo = await self._fetchSessionInfo();
            } catch (err) {
                log.debug('Gemini driver: session info fetch failed');
                log.debug(err);
                self._teardownConnection();
                self._fire('onStateChange', 'error');
                self._fire('onError', err);
                return;
            }
            self.turnmode = self._resolveTurnMode(sessionInfo);
                self.inputlanguage = sessionInfo.inputlanguage || '';
            log.debug('Gemini: turn mode ' + self.turnmode);

            // 3. Open WebSocket.
            try {
                await self._openWebSocket(sessionInfo);
            } catch (err) {
                log.debug('Gemini driver: ws open failed');
                log.debug(err);
                self._teardownConnection();
                self._fire('onStateChange', 'error');
                self._fire('onError', err);
                return;
            }

            // 4. Build mic capture pipeline.
            try {
                await self._startMicPipeline();
            } catch (err) {
                log.debug('Gemini driver: mic pipeline failed');
                log.debug(err);
                self._teardownConnection();
                self._fire('onStateChange', 'error');
                self._fire('onError', err);
                return;
            }

            // 5. Send setup (first turn is queued until setupComplete arrives).
            self._sendSetupAndFirstTurn(sessionInfo.model);
            self._fire('onStateChange', 'connected');
        },

        /**
         * Decide how we signal turn boundaries on this connection. Auto Send on is
         * always plain server VAD; with it off we take the mode the token was minted
         * with, falling back to manual for a provider that does not report one.
         *
         * @param {Object} sessionInfo the token endpoint's response
         * @return {string} one of the TURNMODE_ constants
         */
        _resolveTurnMode: function (sessionInfo) {
            if (this.autocreateresponse) {
                return TURNMODE_AUTO;
            }
            return sessionInfo && sessionInfo.turnmode === TURNMODE_HYBRID
                ? TURNMODE_HYBRID
                : TURNMODE_MANUAL;
        },

        _fetchSessionInfo: function () {
            const self = this;
            const formData = new FormData();
            formData.append('contextid', M.cfg.contextid);
            formData.append('sesskey', M.cfg.sesskey);
            formData.append('voice', self.audiochat_voice);
            formData.append('disablevad', !self.autocreateresponse);
            // When resuming, the handle MUST be baked into the ephemeral token's
            // bidiGenerateContentSetup: the Constrained endpoint honours the token's
            // setup, not handle fields we add over the wire, so without this the
            // session restarts fresh and loses all prior conversation.
            if (self.sessionResumptionToken) {
                formData.append('resumehandle', self.sessionResumptionToken);
            }
            // Ideally this should be an AJAX request to a minilesson web service method,
            // but to keep things "in subplugin" for now we call a subplugin helper file
            return fetch(
                M.cfg.wwwroot + '/mod/minilesson/item/audiochat/geminilive.php',
                {
                    method: 'POST',
                    body: formData
                }
            ).then(function (r) {
                if (!r.ok) {
                    throw new Error('geminilive endpoint returned ' + r.status);
                }
                return r.json();
            });
        },

        _openWebSocket: function (sessionInfo) {
            var self = this;
            return new Promise(function (resolve, reject) {
                var url = sessionInfo.url;
                if (sessionInfo.ephemeralToken) {
                    url += (url.indexOf('?') === -1 ? '?' : '&') +
                        'access_token=' + encodeURIComponent(sessionInfo.ephemeralToken);
                }
                self.ws = new WebSocket(url);
                self.ws.binaryType = 'arraybuffer';
                self.ws.onopen = function () {
                    log.debug('Gemini WS open');
                    self._openedAt = Date.now();
                    resolve();
                };
                self.ws.onerror = function (err) {
                    log.debug('Gemini WS error');
                    log.debug(err);
                    reject(err);
                };
                self.ws.onclose = function (ev) {
                    log.debug('Gemini WS closed');
                    log.debug(ev.code);
                    log.debug(ev.reason);
                    log.debug('Gemini WS close detail: ' + self._diagnostics({
                        code: ev.code,
                        reason: ev.reason,
                        wasClean: ev.wasClean
                    }));
                    self.loadingMessages.clear();
                    // The Live API caps a single connection (~10 min for audio). When it
                    // expires the server closes the socket; recover transparently by
                    // resuming the session on a fresh connection. Skip when WE closed it
                    // (stop / grading / a reconnect already underway).
                    if (!self._intentionalClose && !self.resumingSession &&
                            self.sessionResumptionToken) {
                        log.debug('Gemini: unexpected close, attempting session resumption');
                        self._reconnectSession();
                    }
                };
                self.ws.onmessage = function (ev) { self._handleWSMessage(ev); };
            });
        },

        /**
         * Send the BidiGenerateContentSetup message and queue the first text
         * turn. The first turn is held back until setupComplete is received.
         * @param {string} model
         */
        _sendSetupAndFirstTurn: function (model) {
            var self = this;
            var instructions = self.itemdata.audiochatinstructions || '';

            Fragment.loadFragment(
                'minilessonitem_audiochat',
                'audiochat_fetchstudentsubmission',
                M.cfg.contextid,
                { itemid: self.itemdata.id }
            ).done(function (studentsubmission) {
                log.debug('Gemini: Loaded studentsubmission:');
                log.debug(studentsubmission);
                if (studentsubmission) {
                    instructions = instructions.replace('{student submission}', studentsubmission);
                    self.itemdata.audiochatgradeinstructions =
                        self.itemdata.audiochatgradeinstructions.replace('{student submission}', studentsubmission);
                    self.itemdata.studentsubmission = studentsubmission;
                }

                // Send setup – this MUST be the very first message on the WS.
                // The setup fields must match what is in the ephemeral token's
                // bidiGenerateContentSetup (Constrained endpoint enforces this).
                log.debug('Gemini: sending setup message, WS state:');
                log.debug(self.ws ? self.ws.readyState : 'null');
                self.setupConfig.model = 'models/' + (model || DEFAULT_MODEL);
                // Mirror the turn mode the token carries. Only manual mode turns the
                // VAD off; hybrid keeps it on and pushes its silence window out of
                // reach so our audioStreamEnd is what ends the turn.
                var aad = self.setupConfig.realtimeInputConfig.automaticActivityDetection;
                aad.disabled = self.turnmode === TURNMODE_MANUAL;
                aad.silenceDurationMs = self.turnmode === TURNMODE_HYBRID
                    ? HYBRID_SILENCE_MS
                    : self.silencedurationms;
                // Mirror the transcription language hint the token carries, if it has one.
                self.setupConfig.inputAudioTranscription = self.inputlanguage
                    ? {languageCodes: [self.inputlanguage]}
                    : {};
                self.setupConfig.sessionResumption = {};
                if (self.sessionResumptionToken) {
                    self.setupConfig.sessionResumption.handle = self.sessionResumptionToken;
                    self.sessionResumptionToken = null;
                }
                self._sendWS({
                    setup: self.setupConfig
                });
                log.debug('Gemini: setup message sent');

                // If resuming session then no need to send first instruction.
                if (self.resumingSession) {
                    if (self._micEnabled && self.turnmode === TURNMODE_MANUAL) {
                        // The new socket has no activity open, whatever the old one had.
                        // Re-arm rather than opening one, so a reconnect during silence
                        // does not leave a dangling empty turn behind.
                        self._activityOpen = false;
                        self._awaitingSpeech = true;
                        self._speechFrameCount = 0;
                        self._prerollFrames = [];
                    }
                    self.resumingSession = false;
                    return;
                }

                // Queue the first turn – sent once setupComplete arrives.
                // Instructions are included here (not in setup.systemInstruction)
                // because the Constrained endpoint strips fields not in the token.
                self._pendingFirstMessage = instructions +
                    '\n\nPlease introduce yourself to the student and explain todays topic.';
                log.debug('Gemini: pendingFirstMessage set, setupComplete:');
                log.debug(self._setupComplete);

                // If setupComplete already arrived (unlikely but possible).
                if (self._setupComplete && self._pendingFirstMessage) {
                    self._flushPendingFirstMessage();
                }
            });
        },

        _flushPendingFirstMessage: function () {
            var self = this;
            if (!self._pendingFirstMessage) {
                log.debug('Gemini: _flushPendingFirstMessage called but no pending message');
                return;
            }
            log.debug('Gemini: flushing first message:');
            log.debug(self._pendingFirstMessage);
            // Use realtimeInput.text per Google's WS tutorial (not clientContent).
            self._sendWS({
                realtimeInput: {
                    text: self._pendingFirstMessage
                }
            });
            log.debug('Gemini: first message sent via realtimeInput.text, waiting for model response...');
            self._pendingFirstMessage = null;
        },

        _sendWS: function (obj) {
            var self = this;
            if (self.ws && self.ws.readyState === WebSocket.OPEN) {
                var keys = Object.keys(obj);
                log.debug('Gemini: _sendWS:');
                log.debug(keys.join(','));
                log.debug('WS state:');
                log.debug(self.ws.readyState);
                self.ws.send(JSON.stringify(obj));
            } else {
                log.debug('Gemini: _sendWS SKIPPED, WS not open. State:');
                log.debug(self.ws ? self.ws.readyState : 'null');
            }
        },

        // ── Mic capture pipeline (16 kHz PCM16-LE) ──

        _startMicPipeline: async function () {
            var self = this;
            var AC = window.AudioContext || window.webkitAudioContext;

            try {
                self.inputAudioCtx = new AC({ sampleRate: INPUT_SAMPLE_RATE });
            } catch (_e) {
                self.inputAudioCtx = new AC();
            }

            self.sourceNode = self.inputAudioCtx.createMediaStreamSource(self.mediaStream);
            self.scriptProcessor = self.inputAudioCtx.createScriptProcessor(4096, 1, 1);
            self.scriptProcessor.onaudioprocess = function (event) { self._processAudioFrame(event); };
            // ScriptProcessor must be connected to destination to fire.
            self.scriptProcessor.connect(self.inputAudioCtx.destination);

            // Separate output context at 24 kHz for playback.
            self.outputAudioCtx = new AC({ sampleRate: OUTPUT_SAMPLE_RATE });
            self.nextPlayTime = self.outputAudioCtx.currentTime;
        },

        _processAudioFrame: function (event) {
            var self = this;
            // Do not stream audio until the setup handshake for the CURRENT connection
            // is complete. After a reconnect (goAway/expiry) the mic pipeline is still
            // running, and sending an audio frame before the setup message makes the
            // server reject the socket with 1007 "setup must be the first message".
            if (!self._micEnabled || !self._setupComplete ||
                    !self.ws || self.ws.readyState !== WebSocket.OPEN) {
                return;
            }
            var input = event.inputBuffer.getChannelData(0);

            // Auto Send off: hold the audio back until we hear speech, so a mic-on /
            // mic-off with nothing said never becomes a turn for Gemini to invent a
            // transcript for. Auto Send on leaves the decision to the server VAD.
            if (self._awaitingSpeech) {
                if (self._frameRMS(input) >= SPEECH_RMS_THRESHOLD) {
                    self._speechFrameCount++;
                } else {
                    self._speechFrameCount = 0;
                }

                if (self._speechFrameCount < SPEECH_FRAMES_REQUIRED) {
                    // Keep a little pre-roll so the start of the first word survives.
                    self._prerollFrames.push(new Float32Array(input));
                    if (self._prerollFrames.length > SPEECH_PREROLL_FRAMES) {
                        self._prerollFrames.shift();
                    }
                    return;
                }

                // Speech: open the turn and flush the pre-roll ahead of this frame.
                log.debug('Gemini: speech detected, opening activity');
                self._awaitingSpeech = false;
                self._speechFrameCount = 0;
                self._openActivity();
                var preroll = self._prerollFrames;
                self._prerollFrames = [];
                for (var i = 0; i < preroll.length; i++) {
                    self._sendAudio(preroll[i]);
                }
            }

            self._sendAudio(input);
        },

        /**
         * Root mean square of a frame of normalised (-1..1) samples.
         *
         * @param {Float32Array} frame
         * @return {number}
         */
        _frameRMS: function (frame) {
            var sum = 0;
            for (var i = 0; i < frame.length; i++) {
                sum += frame[i] * frame[i];
            }
            return Math.sqrt(sum / frame.length);
        },

        /**
         * Open a manually delimited user turn, unless one is already open.
         */
        _openActivity: function () {
            var self = this;
            if (self._activityOpen) {
                return;
            }
            self._activityOpen = true;
            self._sendWS({
                realtimeInput: {
                    activityStart: {}
                }
            });
        },

        /**
         * Close the manually delimited user turn, if we opened one. Discards any
         * buffered pre-roll, since audio we never sent is not part of a turn.
         */
        _closeActivity: function () {
            var self = this;
            self._awaitingSpeech = false;
            self._speechFrameCount = 0;
            self._prerollFrames = [];
            if (!self._activityOpen) {
                log.debug('Gemini: no speech in this mic period, sending no turn');
                return;
            }
            self._activityOpen = false;
            self._sendWS({
                realtimeInput: {
                    activityEnd: {}
                }
            });
        },

        _sendAudio: function (input) {
            var self = this;
            var pcm16;
            if (self.inputAudioCtx.sampleRate === INPUT_SAMPLE_RATE) {
                pcm16 = self._floatToPCM16(input);
            } else {
                pcm16 = self._floatToPCM16(
                    self._resampleLinear(input, self.inputAudioCtx.sampleRate, INPUT_SAMPLE_RATE)
                );
            }
            self._sendWS({
                realtimeInput: {
                    audio: {
                        mimeType: 'audio/pcm;rate=' + INPUT_SAMPLE_RATE,
                        data: self._arrayBufferToBase64(pcm16)
                    }
                }
            });
        },

        // ── Audio conversion helpers ──

        _floatToPCM16: function (float32) {
            var buffer = new ArrayBuffer(float32.length * 2);
            var view = new DataView(buffer);
            for (var i = 0; i < float32.length; i++) {
                var s = Math.max(-1, Math.min(1, float32[i]));
                view.setInt16(i * 2, s < 0 ? s * 0x8000 : s * 0x7FFF, true); // little-endian
            }
            return buffer;
        },

        _resampleLinear: function (input, inRate, outRate) {
            var ratio = inRate / outRate;
            var newLen = Math.round(input.length / ratio);
            var out = new Float32Array(newLen);
            for (var i = 0; i < newLen; i++) {
                var pos = i * ratio;
                var left = Math.floor(pos);
                var right = Math.min(left + 1, input.length - 1);
                var frac = pos - left;
                out[i] = input[left] * (1 - frac) + input[right] * frac;
            }
            return out;
        },

        _arrayBufferToBase64: function (buffer) {
            var bytes = new Uint8Array(buffer);
            var binary = '';
            for (var i = 0; i < bytes.byteLength; i++) {
                binary += String.fromCharCode(bytes[i]);
            }
            return btoa(binary);
        },

        _base64ToArrayBuffer: function (base64) {
            var binary = atob(base64);
            var len = binary.length;
            var bytes = new Uint8Array(len);
            for (var i = 0; i < len; i++) {
                bytes[i] = binary.charCodeAt(i);
            }
            return bytes.buffer;
        },

        _pcm16ToFloat32: function (buffer) {
            var view = new DataView(buffer);
            var len = buffer.byteLength / 2;
            var out = new Float32Array(len);
            for (var i = 0; i < len; i++) {
                var v = view.getInt16(i * 2, true); // little-endian
                out[i] = v < 0 ? v / 0x8000 : v / 0x7FFF;
            }
            return out;
        },

        // ── PCM playback ──

        _playPCMChunk: function (base64) {
            var self = this;
            if (!self.outputAudioCtx) {
                return;
            }
            var buf = self._base64ToArrayBuffer(base64);
            var float32 = self._pcm16ToFloat32(buf);
            if (float32.length === 0) {
                return;
            }
            var audioBuffer = self.outputAudioCtx.createBuffer(1, float32.length, OUTPUT_SAMPLE_RATE);
            audioBuffer.copyToChannel(float32, 0);

            var source = self.outputAudioCtx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(self.outputAudioCtx.destination);

            var now = self.outputAudioCtx.currentTime;
            if (self.nextPlayTime < now) {
                self.nextPlayTime = now;
            }
            source.start(self.nextPlayTime);
            self.nextPlayTime += audioBuffer.duration;
        },

        // ── WebSocket message handling ──

        _handleWSMessage: function (ev) {
            var self = this;
            var msg;
            try {
                msg = (typeof ev.data === 'string')
                    ? JSON.parse(ev.data)
                    : JSON.parse(new TextDecoder().decode(ev.data));
            } catch (err) {
                log.debug('Gemini WS parse failed');
                log.debug(err);
                return;
            }

            // setupComplete – gate for first turn.
            if (msg.setupComplete) {
                log.debug('Gemini: setupComplete received');
                self._setupComplete = true;
                if (self._pendingFirstMessage) {
                    self._flushPendingFirstMessage();
                }
                if (self._restoreMicOnResume) {
                    self._restoreMicOnResume = false;
                    // The turn interrupted by the reconnect will never send turnComplete
                    // on this new socket, so explicitly hand the turn back to the user.
                    // onOutputAudioStopped re-opens the mic only if it is not already
                    // active, so a mic that was live across the reconnect is unaffected.
                    self.loadingMessages.clear();
                    self._notifyItems();
                    self._fire('onOutputAudioStopped');
                }
                return;
            }

            if (msg.toolCall || msg.toolCallCancellation) {
                return;
            }

            // The server warns with goAway (carrying timeLeft) shortly before it
            // terminates the connection at the duration limit. Reconnect proactively
            // so the conversation continues without the user noticing a drop.
            if (msg.goAway) {
                log.debug('Gemini: goAway received, timeLeft=' +
                    (msg.goAway.timeLeft || 'unknown'));
                self._reconnectSession();
                return;
            }

            if (msg.sessionResumptionUpdate && msg.sessionResumptionUpdate.resumable) {
                log.debug('Session resumption message received:');
                log.debug(msg);
                self.sessionResumptionToken = msg.sessionResumptionUpdate.newHandle;
            }

            if (msg.usageMetadata) {
                self._lastUsage = msg.usageMetadata;
            }

            if (msg.serverContent) {
                log.debug('Gemini message:');
                log.debug(msg);
                self._handleServerContent(msg.serverContent);
            }
        },

        _handleServerContent: function (content) {
            var self = this;

            // User input transcription.
            if (content.inputTranscription && content.inputTranscription.text) {
                if (!self.currentUserItemId) {
                    self.currentUserItemId = self._newItem('user');
                }
                // Not the end of the student's turn: the transcript can arrive in pieces
                // while they are still speaking. The turn ends when the model replies.
                self.items[self.currentUserItemId].content += content.inputTranscription.text;
            }

            // Model turn (audio + optional text).
            if (content.modelTurn && content.modelTurn.parts) {
                self._startAssistantItem();
                var item = self.items[self.currentAssistantItemId];
                content.modelTurn.parts.forEach(function (part) {
                    if (part.inlineData && part.inlineData.data) {
                        self._playPCMChunk(part.inlineData.data);
                    }
                    if (part.text) {
                        item.content += part.text;
                    }
                });
            }

            // Output transcription (text mirror of spoken audio).
            if (content.outputTranscription && content.outputTranscription.text) {
                self._startAssistantItem();
                self.items[self.currentAssistantItemId].content += content.outputTranscription.text;
            }

            // Interrupted by barge-in.
            if (content.interrupted) {
                if (self.currentAssistantItemId) {
                    self.loadingMessages.delete(self.currentAssistantItemId);
                    self.currentAssistantItemId = null;
                }
            }

            // Turn complete.
            if (content.turnComplete) {
                if (self.currentAssistantItemId) {
                    self.loadingMessages.delete(self.currentAssistantItemId);
                    self.currentAssistantItemId = null;
                }
                self.currentUserItemId = null;
                self._fire('onOutputAudioStopped');
            }

            self._notifyItems();
        },

        /**
         * Open the AI's transcript item on the first content of its reply. The model
         * replying is the reliable sign that the student's turn has ended, so this is
         * where the student's turn is closed too.
         */
        _startAssistantItem: function () {
            var self = this;
            if (self.currentAssistantItemId) {
                return;
            }
            self._fire('onUserSpeechStopped');
            self.currentAssistantItemId = self._newItem('assistant');
            self.loadingMessages.add(self.currentAssistantItemId);
            self._fire('onMicAvailabilityChange', true);
        },

        _newItem: function (role) {
            var self = this;
            var id = 'gemini_' + (++self.itemCounter);
            self.items[id] = {
                id: id,
                usertype: role,
                content: '',
                order: self.itemCounter,
                events: [],
                previous_item_id: null
            };
            return id;
        },

        // ── Mic control ──

        setMicActive: function (active) {
            var self = this;
            self._micEnabled = !!active;
            if (active) {
                if (self.sourceNode && self.scriptProcessor) {
                    try { self.sourceNode.connect(self.scriptProcessor); } catch (e) {
                        log.debug('Gemini: mic connect failed');
                        log.debug(e);
                    }
                }
                if (self.turnmode === TURNMODE_MANUAL) {
                    // Arm speech detection; the activity opens once we hear something.
                    self._awaitingSpeech = true;
                    self._speechFrameCount = 0;
                    self._prerollFrames = [];
                }
            } else {
                if (self.sourceNode && self.scriptProcessor) {
                    try { self.sourceNode.disconnect(self.scriptProcessor); } catch (e) {
                        log.debug('Gemini: mic disconnect failed');
                        log.debug(e);
                    }
                }
                if (self.turnmode === TURNMODE_MANUAL) {
                    self._closeActivity();
                } else {
                    self._sendWS({
                        realtimeInput: {
                            audioStreamEnd: true,
                        }
                    });
                }
            }
        },

        assembleChunks: function (chunks) {
            // 1. Calculate total size
            const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);

            // 2. Pre-allocate the final array
            const combinedArray = new Float32Array(totalLength);

            // 3. Copy chunks into the final array
            let offset = 0;
            for (const chunk of chunks) {
                combinedArray.set(chunk, offset);
                offset += chunk.length;
            }

            return combinedArray;
        },

        // ── Session stop / grading ──

        stopSession: function () {
            var self = this;
            log.debug('Gemini driver: session stopping');
            self.loadingMessages.clear();
            self._fire('onStateChange', 'stopped');
            log.debug('Gemini session stop detail: ' + self._diagnostics());
            self.closeDataChannel();

            if (self.itemdata.audiochatgradeinstructions && self.itemdata.audiochatgradeinstructions !== '') {
                self.sendGradingRequest();
            }
            log.debug('Gemini session stopped');
        },

        /**
         * A one line JSON summary of the session, for working out why a socket closed.
         * Strings only, so it can be pasted from a console.
         * @param {Object} extra anything to add, eg the close code
         * @returns {String}
         */
        _diagnostics: function (extra) {
            var self = this;
            var transcriptchars = 0;
            var itemcount = 0;
            Object.values(self.items || {}).forEach(function (item) {
                itemcount++;
                transcriptchars += (item.content || '').length;
            });
            return JSON.stringify($.extend({
                secondsOpen: self._openedAt ? Math.round((Date.now() - self._openedAt) / 1000) : null,
                intentionalClose: !!self._intentionalClose,
                items: itemcount,
                transcriptChars: transcriptchars,
                usage: self._lastUsage || null
            }, extra || {}));
        },

        /**
         * Grade the finished chat from its transcript.
         *
         * Gemini Live replies only in audio, so a grade asked for inside the session comes
         * back as a transcript of spoken JSON and loses its structure. Instead the transcript
         * goes to the server, which has a text model grade it. The call is tried twice. If it
         * still fails the grading data says so, and the item scores 0.
         */
        sendGradingRequest: function () {
            var self = this;
            var items = Object.values(self.items)
                .sort(function (a, b) { return a.order - b.order; })
                .filter(function (item) { return item.content && item.content.trim() !== ''; })
                .map(function (item) {
                    return {role: item.usertype === 'user' ? 'user' : 'assistant', text: item.content};
                });

            var request = function () {
                return Ajax.call([{
                    methodname: 'minilessonitem_audiochat_grade_chat',
                    args: {cmid: self.cmid, itemid: self.itemdata.id, items: items}
                }])[0];
            };
            var failed = function (reason) {
                log.debug('Gemini grading failed');
                log.debug(reason);
                return {success: false};
            };

            log.debug('Gemini: sending grading request');
            request().catch(function (err) {
                log.debug('Gemini grading call failed, trying again');
                log.debug(err);
                return request();
            }).then(function (result) {
                if (!result || !result.success) {
                    return failed(result);
                }
                return result;
            }).catch(failed).then(function (result) {
                if (result.success) {
                    self.gradingData = {
                        score: result.score,
                        gradeexplanation: result.gradeexplanation,
                        feedback: result.feedback
                    };
                    log.debug('Gemini grading:');
                    log.debug(self.gradingData);
                } else {
                    self.gradingData = {failed: true};
                }
                self._fire('onGradingData', self.gradingData);
                self._fire('onGradingWindowClosed');
                return result;
            });
        },

        abort: function () {
            this.closeDataChannel();
        },

        closeDataChannel: function () {
            this._teardownConnection();
        },

        _teardownConnection: function () {
            var self = this;
            // This is a deliberate teardown (stop / grading / error / release),
            // so the onclose handler must not try to resume the session.
            self._intentionalClose = true;
            if (self.ws) {
                try { self.ws.close(); } catch (e) { log.debug('Gemini: ws close error');log.debug(e); }
                self.ws = null;
            }
            if (self.scriptProcessor) {
                try { self.scriptProcessor.disconnect(); } catch (e) { log.debug(e); }
                self.scriptProcessor = null;
            }
            if (self.sourceNode) {
                try { self.sourceNode.disconnect(); } catch (e) { log.debug(e); }
                self.sourceNode = null;
            }
            if (self.inputAudioCtx) {
                try { self.inputAudioCtx.close(); } catch (e) { log.debug(e); }
                self.inputAudioCtx = null;
            }
            if (self.outputAudioCtx) {
                try { self.outputAudioCtx.close(); } catch (e) { log.debug(e); }
                self.outputAudioCtx = null;
            }
        },

        switchMic: async function (deviceId) {
            var self = this;
            var wasEnabled = self._micEnabled;
            if (self.mediaStream) {
                self.mediaStream.getTracks().forEach(function (t) { t.stop(); });
            }
            try {
                self.mediaStream = await navigator.mediaDevices.getUserMedia({
                    audio: { deviceId: { exact: deviceId } }
                });
                if (self.sourceNode) {
                    try { self.sourceNode.disconnect(); } catch (e) { log.debug(e); }
                }
                self.sourceNode = self.inputAudioCtx.createMediaStreamSource(self.mediaStream);
                if (wasEnabled && self.scriptProcessor) {
                    self.sourceNode.connect(self.scriptProcessor);
                }
                self._fire('onMediaStreamReady', self.mediaStream);
                log.debug('Gemini: switched microphone to ' + deviceId);
            } catch (err) {
                log.debug('Gemini: switchMic failed');
                log.debug(err);
            }
        },

        releaseResources: function () {
            var self = this;
            if (self.mediaStream) {
                self.mediaStream.getTracks().forEach(function (t) { t.stop(); });
                self.mediaStream = null;
            }
            self._teardownConnection();
        },
    };
});
